(async () => {
 const games = await import('/plus/games.js'); const {mountPlus} = await import('/plus/plus.js'); const plus = mountPlus(); await plus.ready;
 const before = document.getElementById('screen').toDataURL(); let started;
 games.registerGamesTab(plus,{onStart:p => {started=p.id;}}); plus.open(); plus.selectTab('games');
 await new Promise(r => setTimeout(r,100));
 const button = document.querySelector('#por-plus-content button');
 if (!button || button.textContent !== 'Start' || !document.querySelector('#por-plus-content').textContent.includes('Pool of Radiance')) throw Error('selector missing');
 button.click(); await new Promise(r => setTimeout(r,50)); if(started !== 'por') throw Error('Start did not choose por');
 plus.close();
 const promise = games.chooseProfile({id:null}); await new Promise(r => setTimeout(r,100));
 const dialog = document.querySelector('[aria-label="Choose a game"]'); if(!dialog) throw Error('front door missing');
 dialog.querySelector('button').click(); const chosen = await promise;
 if(chosen.id !== 'por' || document.contains(dialog)) throw Error('front door selection failed');
 if(before !== document.getElementById('screen').toDataURL()) throw Error('game canvas changed');
 return {pass:true,chosen:chosen.id,startButton:true,canvasUnchanged:true};
})()
